package com.autoops.machine.entity;import jakarta.persistence.*;import java.time.Instant;@Entity @Table(name="machines")public class Machine{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@Column(nullable=false)private String name;@Column(nullable=false)private String hostname;@Column(name="ssh_port",nullable=false)private Integer sshPort=22;@Column(name="operating_system")private String operatingSystem;@Column(name="os_version")private String osVersion;@Column(name="preferred_credential_id")private Long preferredCredentialId;@Column(name="ssh_host_key",columnDefinition="text")private String sshHostKey;@Column(name="ssh_fingerprint")private String sshFingerprint;@Column(name="fingerprint_verified_at")private Instant fingerprintVerifiedAt;@Column(name="created_by")private Long createdBy;@Column(name="created_at")private Instant createdAt=Instant.now();@Column(name="updated_at")private Instant updatedAt=Instant.now();@Column(name="deleted_at")private Instant deletedAt;public Long getId(){return id;}public String getName(){return name;}public void setName(String v){name=v;}public String getHostname(){return hostname;}public void setHostname(String v){hostname=v;}public Integer getSshPort(){return sshPort;}public void setSshPort(Integer v){sshPort=v;}public String getOperatingSystem(){return operatingSystem;}public void setOperatingSystem(String v){operatingSystem=v;}public String getOsVersion(){return osVersion;}public void setOsVersion(String v){osVersion=v;}public String getSshFingerprint(){return sshFingerprint;}public void setSshHostKey(String v){sshHostKey=v;}public void setSshFingerprint(String v){sshFingerprint=v;}public void markFingerprintVerified(){fingerprintVerifiedAt=Instant.now();}}
